import { db } from "@DeshGhuri/db";
import { user } from "@DeshGhuri/db/schema";
import { eq } from "@DeshGhuri/db";

async function checkPassword\(\) {
  const u = await db.query.user.findFirst\({
    where: eq\(user.email, 'abxvein2001@gmail.com'\),
  }\);

  if \(!u\) {
    console.log\('❌ User not found'\);
    return;
  }

  console.log\('📊 Account Info:'\);
  console.log\('Email:', u.email\);
  console.log\('Name:', u.name\);
  console.log\('Has Password:', u.password ? 'Yes ✅' : 'No \(OAuth only\) ❌'\);
  console.log\('Email Verified:', u.emailVerified\);

  if \(!u.password\) {
    console.log\('\\n💡 Your account uses Google OAuth only.'\);
    console.log\('👉 Login with "Continue with Google" button'\);
  } else {
    console.log\('\\n💡 Your account has a password set.'\);
    console.log\('👉 Use "Forgot password?" to reset it'\);
  }
}

checkPassword\(\);
EOF)
